    if isinstance(v, np.ndarray) and v.dtype != object:
        print('  finite shape summary:', v.shape)
    elif isinstance(v, np.ndarray) and v.dtype == object:
        print('  object array len:', len(v), 'first element type:', type(v.flat[0]), 'first element shape:', getattr(v.flat[0], 'shape', None))
        if k == 'blocked':
            print('  first 5 blocked entries:', [v[i,0] if v.ndim==2 else v[i] for i in range(min(5, len(v)))])
        if k == 'envs':
            print('  first 10 envs:', [str(v[i,0]) if v.ndim==2 else str(v[i]) for i in range(min(10, len(v)))])
    else:
        print('  value preview:', str(v)[:300])
for mk, mv in dat['maps'].items():
    print('MAP', mk, 'shape=', mv.shape, 'dtype=', mv.dtype)
